#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_watched && fail 'an IP group named fws_watched exists; nothing was written'
named FW_GROUP_PORT fws_web-all && fail 'a port group named fws_web-all exists; nothing was written'
named FW_GROUP_IP fws_updates && fail 'an IP group named fws_updates exists; nothing was written'
named FW_GROUP_IP fws_web-in_dst && fail 'an IP group named fws_web-in_dst exists; nothing was written'
named FW_GROUP_PORT fws_mail-in && fail 'a port group named fws_mail-in exists; nothing was written'
named FW_GROUP_IP fws_mail-in_dst && fail 'an IP group named fws_mail-in_dst exists; nothing was written'
named FW_GROUP_IP fws_admin-range && fail 'an IP group named fws_admin-range exists; nothing was written'
named FW_GROUP_IP fws_not-servers_src && fail 'an IP group named fws_not-servers_src exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_watched --set .COMMENT 'FWShift: watched'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.66
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_updates --set .COMMENT 'FWShift: updates'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_web-in_dst --set .COMMENT 'FWShift: web-srv, 203.0.113.10'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.80
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_mail-in_dst --set .COMMENT 'FWShift: mail-srv, 203.0.113.25'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin-range --set .COMMENT 'FWShift: admin-range'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10-10.10.5.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_not-servers_src --set .COMMENT 'FWShift: not servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-10.20.0.24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.26-10.20.0.79
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.81-255.255.255.255
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_web-all --set .COMMENT 'FWShift: web-all'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080-8081
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_mail-in --set .COMMENT 'FWShift: mail-in'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 25
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 465
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 587
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_watched
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT block-bad
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_watched
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'web-out: web for the office'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_web-all
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/16 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT updates
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_updates
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_watched
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 123 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT global-ntp
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT 1024:65535 --set .IN_IP 0.0.0.0/0 --set .IN_PORT 1000:2000 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT global-ntp
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 8080:8081 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT web-in
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_web-in_dst
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT mail-in
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_mail-in_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_mail-in
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_watched
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_INCOMING_DMZ_LAN.$N.FROM_IP" fws_watched
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_OUTGOING_DMZWAN.$N.FROM_IP" fws_watched
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.20.0.0/24 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT admin
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_admin-range
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO gre --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.20.0.64/26 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT not-servers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_not-servers_src
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF REJECT --set .LOG no --set .COMMENT global-block
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_watched
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 10.10.0.0/16 --set .COMMENT 'trust-out snat-lan'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
